{"path": "public/index.html", "anchor_text": "const API = window.location.origin;", "text": "

// Fetch client config
fetch('/api/client-config')
  .then(response => response.json())
  .then(config => {
    const apiKey = config.tilerApiKey;
    const basemapConfigured = config.basemapConfigured;

    // Update tile layer URL with API key if configured
    if (basemapConfigured) {
      L.tileLayer('https://{s}.basemaps.example.com/dark_all/{z}/{x}/{y}{r}.png?api_key=' + apiKey, {
        attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OSM</a> &copy; <a href="https://tiler.test/attributions">Tiler</a>',
        subdomains: 'abcd',
        maxZoom: 19,
      }).addTo(map);
    } else {
      // Display notice if API key is missing
      const notice = document.createElement('div');
      notice.className = 'basemap-notice';
      notice.textContent = 'Basemap unavailable: TILER_API_KEY is not configured. See README (Configuration).';
      document.body.appendChild(notice);
    }
  })
  .catch(error => {
    console.error('Error fetching client config:', error);
  });"}

